  "hqg-fbe3920cd3976b128c994892": "24dfc770ae7b9e706152c6a838c12154b20653dd67d4627f3a1d7862f6d8446c",
  "hqg-fc2b702069e261fe05c2c87b": "bba629fca79ff95bf91d8cfaafab3c47d53f3157b4f5159a54846c7933ca7479",
  "hqg-fe035b1ff253fc623170d7db": "241ac7152d0c25f4b450bfb4b71647f4ac832ea6e6f8a2c0c36fb75e4ddaa711",
  "hqg-ffb950f5ce33ce98940978e1": "bb53075b9f6a3ce139492bcf3d069626aab875c465e9f4eca2b9867a0e94ff0c",
  "hqg-ffec521cb7bf3552ae2a3a17": "cf8dc30027d4acd2a4a6c7d94b24a5aa549d422c60ec1d859e850298eac0bd5b"
}$pins$::jsonb;
 expected_hash text;
 card jsonb;
 child_age integer;
 previous hq.goals;
 binding hq.catalog_goal_sources;
 card_keywords text[];
BEGIN
 SELECT k.age INTO child_age FROM hq.children k
 WHERE k.id=selected_child AND k.family_id IN (SELECT hq.my_families()) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'catalog_not_authorized'; END IF;
 IF child_age IS DISTINCT FROM expected_age THEN RAISE EXCEPTION 'catalog_stale_child'; END IF;
 expected_hash := allowed->>wanted_goal;
 IF expected_hash IS NULL OR octet_length(canonical_json)>65536
    OR encode(sha256(convert_to(canonical_json,'UTF8')),'hex') IS DISTINCT FROM expected_hash THEN
   RAISE EXCEPTION 'catalog_untrusted_source';
 END IF;
 card := canonical_json::jsonb;
 IF selected_setting IS NULL OR NOT ((card#>'{stacking,contexts}') ? selected_setting)
    OR child_age < (card#>>'{age,min}')::integer OR child_age > (card#>>'{age,max}')::integer
    OR card->>'intent_class' NOT IN ('general_wellbeing','targeted_skill_support')
    OR (card#>>'{retrieval,available_by_default}')::boolean IS NOT TRUE
    OR card#>>'{retrieval,language}' <> 'en' OR card->>'catalog_version' <> '0.1.0' THEN
   RAISE EXCEPTION 'catalog_ineligible';
 END IF;
 card_keywords := ARRAY(SELECT jsonb_array_elements_text(card#>'{retrieval,search_terms}'));
 PERFORM pg_advisory_xact_lock(hashtextextended('hq.source-goal:'||wanted_goal,0));
 IF EXISTS(SELECT 1 FROM hq.catalog_goal_sources WHERE source_id=card->>'id' AND goal_id<>wanted_goal) THEN
   RAISE EXCEPTION 'catalog_source_collision';
 END IF;
 SELECT * INTO previous FROM hq.goals WHERE id=wanted_goal FOR UPDATE;
 IF FOUND THEN
   IF NOT previous.is_active THEN RAISE EXCEPTION 'catalog_retired'; END IF;
   SELECT * INTO binding FROM hq.catalog_goal_sources WHERE goal_id=wanted_goal;
   IF binding.goal_id IS NULL OR previous.title IS DISTINCT FROM card->>'title'
      OR previous.description IS DISTINCT FROM card->>'description'
      OR binding.source_id IS DISTINCT FROM card->>'id'
      OR binding.concept_id IS DISTINCT FROM card->>'concept_id'
      OR binding.category_id IS DISTINCT FROM card->>'category_id'
      OR binding.catalog_version IS DISTINCT FROM '0.1.0'
      OR binding.record_sha256 IS DISTINCT FROM expected_hash
      OR binding.snapshot_id IS DISTINCT FROM '22cec20089fee49e76ee76861b01a199e05f765ec19a2f1911eddef1088828df' THEN
     RAISE EXCEPTION 'catalog_existing_conflict';
   END IF;
   RETURN false;
 END IF;
 INSERT INTO hq.goals(id,title,description,keywords)
 VALUES(wanted_goal,card->>'title',card->>'description',card_keywords);
 INSERT INTO hq.catalog_goal_sources(goal_id,source_id,concept_id,category_id,catalog_version,record_sha256,snapshot_id)
 VALUES(wanted_goal,card->>'id',card->>'concept_id',card->>'category_id','0.1.0',expected_hash,'22cec20089fee49e76ee76861b01a199e05f765ec19a2f1911eddef1088828df');
 RETURN true;
END
$function$;
REVOKE ALL ON FUNCTION hq.materialize_catalog_goal(uuid,text,integer,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION hq.materialize_catalog_goal(uuid,text,integer,text,text) TO hq_api;
